<div class="field"><label for="<?= e($field) ?>"><?= e($label) ?> <?= $required ? '<span class="required">*</span>' : '<span class="optional">(facultatif)</span>' ?></label><input id="<?= e($field) ?>" name="<?= e($field) ?>" value="<?= e($data[$field]) ?>" placeholder="<?= e($placeholder) ?>" maxlength="<?= $max ?>" <?= $required ? 'required' : '' ?> <?= isset($errors[$field]) ? 'aria-invalid="true" aria-describedby="error-' . e($field) . '"' : '' ?>><?php if (isset($errors[$field])): ?><span class="field-error" id="error-<?= e($field) ?>"><?= e($errors[$field]) ?></span><?php endif ?></div>
